const registry = { click: onClick, hover: onHover, key: onKey, scroll: onScroll /* ...many */ };
function handleAll(events) {
  for (const ev of events) {
    registry[ev.type](ev);   // ONE megamorphic call site for all types
  }
}

model.en:
Split the single many-target site into several single-target sites so the hot, common types each hit a monomorphic, inlinable call. A <code>switch</code> on the type does this — each <code>case</code> is its own call site with exactly one callee identity:<br><code>function handleAll(events) {
  for (const ev of events) {
    switch (ev.type) {
      case 'click':  onClick(ev);  break;  // monomorphic site
      case 'hover':  onHover(ev);  break;  // monomorphic site
      case 'key':    onKey(ev);    break;
      case 'scroll': onScroll(ev); break;
      default:       registry[ev.type](ev); // rare/long tail stays generic
    }
  }
}</code><br>The hot branches now have one callee identity each, so TurboFan can inline them; only the rare long tail keeps the generic indirect call. The variety of identities is no longer concentrated on a single hot line.

model.ru:
Раздели единственную многоцелевую точку на несколько одноцелевых, чтобы горячие частые типы попадали каждый в monomorphic, инлайнимый вызов. <code>switch</code> по типу делает это — каждый <code>case</code> это своя точка вызова ровно с одной идентичностью callee:<br><code>function handleAll(events) {
  for (const ev of events) {
    switch (ev.type) {
      case 'click':  onClick(ev);  break;  // monomorphic точка
      case 'hover':  onHover(ev);  break;  // monomorphic точка
      case 'key':    onKey(ev);    break;
      case 'scroll': onScroll(ev); break;
      default:       registry[ev.type](ev); // редкий длинный хвост остаётся общим
    }
  }
}</code><br>У горячих веток теперь по одной идентичности callee, поэтому TurboFan может их заинлайнить; только редкий длинный хвост сохраняет общий косвенный вызов. Разнообразие идентичностей больше не сконцентрировано на одной горячей строке.

tasks.starter:
function makeSite() {
  const names = [];
  return {
    invoke(fn, arg) {
      if (!names.includes(fn.name)) names.push(fn.name); // track by name
      return fn(arg);
    },
    distinct() { return names.length; },
  };
}

