function dispatch(events, ctx) {
  for (const ev of events) {
    // look up and immediately wrap the handler each time
    const handler = registry[ev.type] || (() => {});
    const wrapped = (e) => handler(e, ctx);   // fresh arrow per event
    wrapped(ev);                              // single call site for ALL handler types
  }
}
